from collections import Counter

def transform(grid):
    g=[row[:] for row in grid]
    H,W=len(g),len(g[0])
    bg=Counter(v for row in g for v in row).most_common(1)[0][0]
    # get contiguous non-background runs along a specified edge, each item color, indices
    def runs(vals):
        out=[]; i=0
        while i<len(vals):
            if vals[i]==bg:
                i+=1; continue
            col=vals[i]; j=i+1
            while j<len(vals) and vals[j]==col: j+=1
            out.append((col,list(range(i,j))))
            i=j
        return out
    pairs=[]
    # bars on left/right edges: vertical runs
    L=runs([g[r][0] for r in range(H)])
    R=runs([g[r][W-1] for r in range(H)])
    for c,ii in L:
        for d,jj in R:
            if c==d and len(ii)==len(jj): pairs.append(('v',c,ii,jj))
    # top/bottom edges: horizontal runs
    T=runs(g[0]); B=runs(g[H-1])
    for c,ii in T:
        for d,jj in B:
            if c==d and len(ii)==len(jj): pairs.append(('h',c,ii,jj))
    if not pairs: return g
    # choose the pair whose bar color has least count among qualifying and which has nonbar pixels to identify signal
    pc=Counter(p[1] for p in pairs)
    marker=min(pc, key=lambda c: Counter(v for row in g for v in row)[c])
    # ensure all selected pair color marker
    pairs=[p for p in pairs if p[1]==marker]
    signal_colors={v for row in g for v in row if v not in (bg,marker,4)}
    if not signal_colors: return g
    # Usually one signal color; use each and generate matching rays. If multiple choose least common
    sig=min(signal_colors,key=lambda c:Counter(v for row in g for v in row)[c])
    for orient,mark,idx1,idx2 in pairs:
        active=set()
        for r in range(H):
            for c in range(W):
                if g[r][c]==sig:
                    index = c if orient=='h' else r
                    if index in idx1 or index in idx2:
                        active.add(index)
        if orient=='v':
            # idx values are rows; left ray goes right and right ray goes left
            for index in active:
                for start,step in [(0,1),(W-1,-1)]:
                    r=index
                    c=start+step
                    while 0<=c<W:
                        if g[r][c]==sig:
                            g[r][c]=4; break
                        # preserve edge markers of paired objects; otherwise fill
                        if g[r][c]==marker and (c==0 or c==W-1): break
                        g[r][c]=sig
                        c+=step
        else:
            # idx values are columns; top ray down, bottom ray up
            for index in active:
                for start,step in [(0,1),(H-1,-1)]:
                    c=index
                    r=start+step
                    while 0<=r<H:
                        if g[r][c]==sig:
                            g[r][c]=4; break
                        if g[r][c]==marker and (r==0 or r==H-1): break
                        g[r][c]=sig
                        r+=step
    return g

